#include <bits/stdc++.h>
using namespace std;

char ch[20][50] = {
    "vaporeon", "jolteon", "flareon", "espeon",
    "umbreon", "leafeon", "glaceon", "sylveon"
};
char tar[50];
int ok[50];
int n;

int main() {
    memset(ok, -1, sizeof(ok));

    scanf("%d", &n);
    scanf("%s", tar);

    for (int i = 0; i < 8; i++) {
        if (strlen(ch[i]) != n) {
            ok[i] = 0;
            continue;
        }

        for (int j = 0; j < n; j++) {
            if (tar[j] != '.' && tar[j] != ch[i][j]) {
                ok[i] = 0;
                break;
            }
        }
    }

    for (int i = 0; i < 8; i++) {
        if (ok[i]) {
            printf("%s", ch[i]);
            break;
        }
    }

    return 0;
}

